describe('Multiple File Upload', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should successfully upload multiple files at once', () => {
    // Intercept the file upload API endpoint
    cy.intercept('POST', '/api/uploads/batch').as('uploadBatch');

    // Select multiple files from the file input
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/file1.pdf', { force: true });
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/file2.docx', { force: true });
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/file3.jpg', { force: true });

    // Verify files are selected
    cy.get('[data-testid="file-input"]').should('have.files.count', 3);

    // Click the upload button
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the upload batch API call
    cy.wait('@uploadBatch');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Files uploaded successfully');

    // Verify file names are displayed
    cy.get('[data-testid="uploaded-files-list"]').should('be.visible');
    cy.get('[data-testid="uploaded-files-list"]').should('contain', 'file1.pdf');
    cy.get('[data-testid="uploaded-files-list"]').should('contain', 'file2.docx');
    cy.get('[data-testid="uploaded-files-list"]').should('contain', 'file3.jpg');

    // Verify file sizes are displayed
    cy.get('[data-testid="file-size"]').should('be.visible');
    cy.get('[data-testid="file-size"]').should('contain', '1.2 MB');
    cy.get('[data-testid="file-size"]').should('contain', '2.5 MB');
    cy.get('[data-testid="file-size"]').should('contain', '3.1 MB');

    // Verify error message does not appear
    cy.get('[data-testid="error-message"]').should('not.exist');
  });

  it('should handle uploading multiple files with invalid file types', () => {
    // Intercept the file upload API endpoint
    cy.intercept('POST', '/api/uploads/batch').as('uploadBatch');

    // Select multiple files, including an invalid file type
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/file1.pdf', { force: true });
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/file2.docx', { force: true });
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/invalid-file.exe', { force: true });

    // Verify files are selected
    cy.get('[data-testid="file-input"]').should('have.files.count', 3);

    // Click the upload button
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the upload batch API call
    cy.wait('@uploadBatch');

    // Verify error message appears for invalid file
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid file type');

    // Verify success message does not appear
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify only valid files are listed
    cy.get('[data-testid="uploaded-files-list"]').should('be.visible');
    cy.get('[data-testid="uploaded-files-list"]').should('contain', 'file1.pdf');
    cy.get('[data-testid="uploaded-files-list"]').should('contain', 'file2.docx');

    // Verify error message is visible
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'File type not supported');
  });
});
